#pragma once
#include <optional>
#include "update_payload.hpp"

namespace ohno {
struct UpdateConnection {
    std::wstring server;
    std::string certificate_pem,release_public_key,device_id,device_key;
    // The service caller owns the identity buffer; erase device_key after use.
};
struct StagedUpdate {UpdateRevision revision;UpdateManifest manifest;std::string document;};
// Holds no teacher maintenance password. Device identity is independently
// generated by existing enrollment, including after an OEM image clone.
std::optional<StagedUpdate> fetch_staged_update(WindowsUpdateJournal& storage,const UpdateConnection& connection,
    const UpdateJournal& current,HANDLE stop_event=nullptr);
// Fresh online decision immediately before selector switch; not a saved ticket.
bool authorize_staged_update(const UpdateConnection& connection,const StagedUpdate& update,HANDLE stop_event=nullptr);
}
